function isLeap(y){ y=+y; if(!(y>0)) return false; return (y%4===0 && y%100!==0) || y%400===0; }
function daysInFeb(y){ return isLeap(y)?29:28; }
function daysInYear(y){ return isLeap(y)?366:365; }
function leapYearsBetween(a,b){ a=+a;b=+b; if(isNaN(a)||isNaN(b)) return {error:'年份须为数字'}; if(a>b){var t=a;a=b;b=t;} var c=0; for(var y=a;y<=b;y++) if(isLeap(y)) c++; return c; }
var EXPORTS={isLeap:isLeap, daysInFeb:daysInFeb, daysInYear:daysInYear, leapYearsBetween:leapYearsBetween};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LeapYearForgePure = EXPORTS; }
